Plot.plot({
  color: { legend: true },
  marks: [
    Plot.arc([
      { task: "meetings", hours: 30 },
      { task: "coding", hours: 50 },
      { task: "review", hours: 20 }
    ], {
      x: 0,
      y: 0,
      r: 200,
      fill: "task",
      stroke: "white",
      strokeWidth: 2,
      channels: { value: "hours" }
    })
  ],
  width: 500,
  height: 500,
  x: { axis: null },
  y: { axis: null }
})

(() => {
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const w = 360, r = 140;
  const color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arcs = d3.pie().value(d => d.value).sort(null)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.62).outerRadius(r * 0.62);
  const svg = d3.create("svg").attr("viewBox", [-w / 2, -w / 2, w, w]).attr("width", w).attr("height", w);
  const g = svg.selectAll("g").data(arcs).join("g");
  g.append("path").attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  g.append("text").attr("transform", d => `translate(${label.centroid(d)})`).attr("text-anchor", "middle")
    .attr("fill", "white").attr("font-size", 13).text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
})()

